payload_role_elfldr: "بارگذار ELF، پیش از helper برنامه PS5Upload بارگذاری می‌شود",
payload_desc_elfldr: "بارگذاری که payloadها را دریافت می‌کند. آن را پیش از helper برنامه PS5Upload با جیلبریک یا autoloader بارگذاری کنید. ارسال آن به بارگذاری نیاز دارد که از قبل کار می‌کند: نمی‌تواند پورت بسته را باز کند. پس از اتصال helper، PS5Upload می‌تواند بارگذار استاندارد در حال اجرا را با نسخهٔ وصله‌شدهٔ خود جایگزین کند.",
