payloads_load_failed: "بارگذاری کاتالوگ ناموفق بود",
payloads_inventory_failed: "خواندن کش payload محلی ناموفق بود",
payloads_loading: "در حال بارگذاری کاتالوگ…",
payloads_no_host: "هیچ میزبان PS5 تنظیم نشده. ابتدا در صفحه‌ی Connection متصل شوید.",
payloads_pm_store: "ذخیره در Payload Manager",
payloads_pm_store_tooltip: "این فایل را روی PS5 در Payload Manager نگه می‌دارد تا از آنجا اجرا یا هنگام بوت بارگذاری شود.",
payloads_pm_store_confirm_title: "پوشهٔ «{folder}» در Payload Manager جایگزین شود؟",
payloads_pm_store_confirm_same: "Payload Manager از قبل {name} را دارد. ذخیره آن را جایگزین می‌کند و فایل‌های دیگر آن پوشه را حذف می‌کند.",
payloads_pm_store_confirm_other: "Payload Manager از قبل پوشهٔ «{folder}» را دارد. ذخیره در آن فایل‌های دیگر آنجا را حذف می‌کند (معمولاً نسخهٔ قدیمی‌تر).",
