pm_error_title: "دسترسی به Payload Manager ممکن نشد",
pm_probing: "در حال جستجوی Payload Manager روی PS5…",
pm_absent_title: "Payload Manager روی این PS5 اجرا نیست",
pm_absent_body: "Payload Manager (itsPLK) پی‌لودها را روی کنسول نگه می‌دارد و می‌تواند هنگام بوت بارگذاری‌شان کند. آن را از برگهٔ کاتالوگ بفرستید یا روی PS5 اجرا کنید، سپس به اینجا برگردید.",
