upload_add_to_queue_tooltip: "این بارگذاری را بدون شروع به صف اضافه کن",
upload_dialog_resume_desc: "از فایل‌هایی که از قبل آنجا هستند صرف‌نظر می‌کند؛ فقط آنچه جدید یا تغییر کرده ارسال می‌شود. اندازه‌ی فایل‌ها را مقایسه می‌کند — تأیید هر shard BLAKE3 در بارگذاری واقعی هر مغایرتی را می‌گیرد.",
