upload_status_preparing_hint: "(ساخت فهرست فایل و خواندن دسته‌ی اول — پوشه‌های بزرگ یا دیسک‌های منبع کند یک دقیقه طول می‌کشند)",
upload_wrapped_hint_intro: "این پوشه به‌تنهایی یک بازی نیست، اما شامل یک پوشه‌ی بازی درون خود است:",
upload_wrapped_hint_suffix: ". آیا قصد داشتید آن یکی را بارگذاری کنید؟",
upload_mount_after_desc: "پس از رسیدن تصویر به PS5، payload آن را از طریق بک‌اند LVD کرنل متصل می‌کند. پیش‌فرض خاموش — اگر می‌خواهید تصویر هم متصل شود تا عنوان فوراً در لانچر ظاهر شود روشن کنید.",
upload_mount_readonly_desc: "توصیه‌شده. جلوگیری می‌کند از نوشتن داده‌ی ذخیره توسط PS5 در تصویر (که بی‌صدا فایل روی دیسک را خراب و اتصال دوباره را می‌شکند). وقتی قصد ویرایش تصویر را دارید خاموش کنید — جایگزینی فایل‌ها، افزودن DLC یا اعمال پچ backport — و به یاد داشته باشید این ویرایش‌ها دائمی هستند.",
upload_dest_will_create: "اگر پوشه‌ی مقصد هنوز روی PS5 وجود ندارد، هنگام شروع بارگذاری ساخته می‌شود.",
