// Humanized error copy — surfaced by lib/humanizeError.ts. {placeholders}
// are substituted at runtime; keep them verbatim when translating.
err_unmount_busy:
  "نمی‌توان جدا کرد: بازی داخل این تصویر در حال حاضر روی PS5 در حال اجراست. از آن خارج شوید (PS Home ← بستن بازی) و دوباره تلاش کنید.",
err_uninstall_refused:
  "PS5 حذف این بازی را رد کرد ({code})، پس بازی هنوز نصب است. PS5 را دوباره راه‌اندازی کنید و دوباره امتحان کنید؛ اگر باز هم رد کرد، آن را از تنظیمات ← فضای ذخیره‌سازی در PS5 حذف کنید.",
err_uninstall_unavailable:
  "سفت‌افزار این PS5 هیچ راهی برای حذف در اختیار کمک‌یار نمی‌گذارد و بازی هنوز نصب است. آن را از تنظیمات ← فضای ذخیره‌سازی در PS5 حذف کنید.",
installed_uninstall_still_present:
  "PS5 حذف را پذیرفت، اما {name} هنوز روی کنسول است. حذف یک بازی بزرگ ممکن است چند دقیقه طول بکشد: کمی بعد دوباره به‌روزرسانی کنید. اگر باقی ماند، آن را از تنظیمات ← فضای ذخیره‌سازی در PS5 حذف کنید.",
err_unmount_permission:
  "نمی‌توان جدا کرد: کرنل با EACCES/EPERM رد کرد. ممکن است payload اعتبار root را از دست داده باشد — از Connection ← Send payload دوباره بارگذاری کنید.",
err_not_enough_space: "فضای خالی این رایانه کافی نیست: {need} لازم است و {free} خالی است. کمی فضا آزاد کنید و دوباره امتحان کنید.",
err_link_changed: "فایل این لینک هنگام خواندن تغییر کرد، پس آنچه تا اینجا خوانده شده با آن کامل نمی‌شود. دوباره شروع کنید.",
err_pair_pending: "PS5 جفت‌شدن را رد کرد (80108b03). روی PS5 کاربری که با آن بازی می‌کنید باید واردشده نشان داده شود (Settings › Users and Accounts) و «فعال‌سازی Remote Play» باید روشن باشد (تنظیمات › سیستم › Remote Play). اگر یکی خاموش یا خاکستری است: ورود آفلاین را در «راه‌اندازی «بازی»» اجرا کنید، PS5 را دوباره راه‌اندازی کنید و دوباره «جفت کردن» را بزنید. PS5ای که به محیط NP ‏sp-int تغییر داده شده هم رد می‌کند: هنگام جفت کردن آن را به np برگردانید. باز هم رد شد؟ «جفت‌سازی با PIN نمایش‌داده‌شده روی PS5» را بزنید و عدد نمایش‌داده‌شده در تنظیمات › سیستم › Remote Play › Link Device را وارد کنید.",
err_unpack_no_space: "فضای خالی این درایو برای ایمیج باز‌شده کافی نیست. به اندازهٔ کامل ایمیج به‌اضافهٔ ۱ گیبی‌بایت نیاز است.",
err_unpack_exists: "فایلی با نام ایمیج در این پوشه هست. اول آن را جابه‌جا کنید یا نامش را عوض کنید.",
err_unpack_bad: "این فایل به‌عنوان ایمیج فشردهٔ بازی خوانده نشد یا خراب است. چیزی نوشته نشد.",
err_unpack_busy: "کنسول در حال باز کردن فایل دیگری است. صبر کنید تا تمام شود، سپس دوباره امتحان کنید.",
err_unpack_mount: "کنسول نتوانست این فایل را برای باز کردن فشرده‌سازی باز کند. اگر ShadowMount+ آن را مانت کرده یا بازی‌ای از آن در حال اجراست، بازی را ببندید و دوباره امتحان کنید. چیزی نوشته نشد.",
err_extract_no_space: "فضای خالی این درایو برای همه محتوای آرشیو کافی نیست. چیزی نگه داشته نشد.",
err_extract_exists: "پوشه‌ای با این نام از قبل اینجا هست. «نگه داشتن هر دو» یا «ادغام» را انتخاب کنید.",
err_extract_busy: "کنسول در حال استخراج آرشیو دیگری است. صبر کنید تمام شود، سپس دوباره امتحان کنید.",
err_extract_password_required: "این آرشیو با گذرواژه محافظت شده است. گذرواژه‌اش را وارد کنید.",
err_extract_wrong_password: "گذرواژه نادرست است.",
err_extract_rar_encrypted: "آرشیوهای RAR دارای گذرواژه روی کنسول استخراج نمی‌شوند. RAR بدون گذرواژه کار می‌کند؛ این یکی را روی رایانه استخراج کنید.",
err_extract_unsupported_method: "آرشیو از روش فشرده‌سازی‌ای استفاده می‌کند که کنسول نمی‌تواند استخراج کند.",
err_extract_corrupt: "آرشیو خراب یا ناقص است.",
