err_extract_missing_volume: "بخشی از این آرشیو چندتکه نیست: {name}. همه بخش‌ها را در یک پوشه بگذارید.",
err_extract_loader: "بارگذار ELF کنسول (درگاه 9021) پاسخ نداد، پس استخراج‌کننده اجرا نشد. elfldr را دوباره بارگذاری کنید و دوباره امتحان کنید.",
