fs_replace_confirm_body: "\"{name}\" بازنویسی می‌شود و محتوای قدیمی برای همیشه از بین می‌رود. اگر این داخل یک تصویر بازی متصل است، یک فایل بد می‌تواند بوت بازی را متوقف کند.",
