backport_inspecting: "در حال بررسی خانواده‌های کتابخانه‌ی نصب‌شده…",
backport_summary: "این بازی را به جفت SDK نسخه‌ی FW 4 downgrade می‌کند و مجموعه‌ی {count} کتابخانه‌ای که {set} ارائه می‌دهد را نصب می‌کند. یک مجموعه کامل نصب می‌شود — مخلوط کردن کتابخانه‌ها بین بازی‌ها دلیل شکست اجرای backport است.",
settings_card_fakelibs: "کتابخانه‌های backport",
backport_verify_unpatched: "این عنوان backport نشده",
backport_verify_unpatched_body: "eboot آن هنوز نسخه‌ی SDK اصلی را دارد، بنابراین روی این فریم‌ور نمی‌تواند اجرا شود هر کتابخانه‌ای که نصب شود — مجموعه‌ی کتابخانه مشکل نیست. backport را دوباره اجرا کنید؛ اگر مدام اتفاق می‌افتد پچ SDK اعمال نمی‌شود.",
backport_no_larger: "این بازی به کتابخانه‌هایی نیاز دارد که هیچ‌کدام از مجموعه‌های شما ندارد. یک بسته‌ی کامل‌تر وارد کنید، یا کنسول دیگری را اسکن کنید.",
backport_verifying: "در حال اجرا و تماشا — اجرای ناموفق دوباره تلاش می‌شود، چون اجرا به‌تنهایی غیرقابل اعتماد است و یک شکست چیزی را ثابت نمی‌کند.",
backport_verify_running: "در حال اجراست — به گیم‌پلی می‌رسد؟",
backport_verify_running_body: "بازی پس از یک دقیقه هنوز بالاست ({threads} رشته). یعنی در بارگذاری کرش نکرد، اما نه اینکه بازی می‌شود — صفحه را بررسی کنید. اگر کار می‌کند نگهش دارید، یا Undo کنید و مجموعه‌ی بعدی را امتحان کنید.",
backport_verify_missing: "به کتابخانه‌های بیشتری نیاز دارد",
backport_verify_missing_body: "بازی تابعی را فراخوانی کرد که هیچ‌کدام از کتابخانه‌های نصب‌شده ارائه نمی‌دهد. {count} مجموعه‌ی بزرگ‌تر برای امتحان باقی مانده.",
backport_verify_wrong: "کتابخانه‌های اشتباه برای این بازی",
backport_verify_wrong_body: "این عنوان به‌درستی پچ شده اما با این کتابخانه‌ها شروع نشد، بنابراین آن‌ها آن چیزی که نیاز دارد نیستند. {count} مجموعه‌ی دیگر برای امتحان باقی مانده.",
backport_verify_unknown: "نمی‌توانستیم بگوییم آیا کار کرد",
backport_verify_unknown_body: "اجراها توافق نداشتند، بنابراین این چیزی درباره‌ی کتابخانه‌ها نمی‌گوید — اجرا به‌تنهایی به‌قدر کافی شکست می‌خورد که یک نتیجه‌ی مختلط بی‌معنا باشد. خودتان اجرایش کنید، و اگر بازی نکرد Undo کنید.",
