fs_upload_interrupted_notice: "یک کپی به PS5 قطع شد. برای ادامه، «فایل‌ها» را باز کنید.",
installed_launch_smp_refused: "PS5 از اجرای این بازی خودداری کرد (0x80940033) با اینکه kstuff در حال اجراست. ShadowMount+ بازی را هنگام شروع آن سوار می‌کند و این اتفاق نیفتاد. هر بازی در حال اجرا را ببندید، ShadowMount+ را دوباره از Payloads بفرستید و سپس «اجرا» را بزنید.",
connection_mac_local_network_hint: "ممکن است macOS دسترسی این برنامه به شبکهٔ محلی شما را مسدود کرده باشد. System Settings ← Privacy & Security ← Local Network را باز کنید، به PS5Upload اجازه دهید و دوباره بررسی کنید.",
