kept_title: "نگه‌داشته‌شده توسط ps5upload",
kept_intro: "پوشه‌هایی که خود ps5upload روی این کنسول می‌نویسد و حجم هر کدام. فایل‌های موقت و آزمایشی را می‌توان پاک کرد؛ بسته‌ها و پشتیبان‌های ذخیرهٔ شما از اینجا فقط باز می‌شوند و هرگز حذف نمی‌شوند.",
