volumes_store_pkg_copies: "نسخه‌های بسته را اینجا نگه دار",
volumes_pkg_copies_hint: "کار این گزینه: «آپلود و نصب» ابتدا فایل ‎.pkg را روی PS5 کپی می‌کند و سپس از همان نسخه نصب می‌کند. این فقط تعیین می‌کند آن نسخه‌ها روی کدام درایو بمانند. محل نصب بازی‌ها را تغییر نمی‌دهد (PS5 آن را در تنظیمات ذخیره‌سازی خودش تعیین می‌کند) و «استریم و نصب» هیچ نسخه‌ای نگه نمی‌دارد. اگر درایو انتخاب‌شده متصل نباشد، نسخه‌ها به حافظهٔ داخلی می‌روند.",
