stop: "توقف",
activity_description_v2: "هر کاری که برنامه روی کنسول‌های شما انجام می‌دهد و انجام داده است: بارگذاری‌ها، دانلودها، نصب‌ها و عملیات فایل. هر کدام را از اینجا متوقف یا دوباره امتحان کنید. ۱۰۰ مورد اخیر، حتی پس از راه‌اندازی دوباره، نگه داشته می‌شود.",
health_subtitle_v2: "بررسی می‌کند که PS5، این برنامه و شبکهٔ میان آن‌ها کار می‌کنند، اگر کار نکنند می‌گوید چه چیزی را درست کنید، و سرعت انتقال فایل میان آن‌ها را اندازه می‌گیرد.",
remotePlay_subtitle_v2: "این PS5 را برای Remote Play آماده کنید و PIN‌ای بگیرید که برنامهٔ PS Remote Play را به آن پیوند می‌دهد.",
saves_description_v2: "داده‌های ذخیره روی PS5، یک ورودی برای هر بازی. از ذخیره‌های یک بازی در قالب ‎.zip روی این رایانه پشتیبان بگیرید و بعداً بازیابی کنید.",
shell_description_v2: "فرمان‌هایی تایپ کنید که روی PS5 و درون پردازهٔ کمک‌کار اجرا می‌شوند. برای کاربران پیشرفته. خروجی هر فرمان به ۲۵۶ کیلوبایت محدود است؛ کلیدهای بالا و پایین فرمان‌های قبلی را برمی‌گردانند.",
"arcpkg.links.go": "دانلود {count} فایل",
"arcpkg.links.help": "پیوند مستقیم آرشیو، یا هر بخش از آرشیو چندبخشی را جای‌گذاری کنید، هر خط یکی. فایل‌ها روی این رایانه (Downloads/ps5upload) دانلود می‌شوند که باید برای همهٔ آن‌ها جا داشته باشد؛ سپس بسته‌های درونشان همان‌طور که در بالا آمده روی PS5 باز می‌شوند.",
"arcpkg.links.kept": "{count} فایل دانلودشده در {dir} هستند. نگه داشته می‌شوند تا بتوانید نصب را دوباره امتحان کنید؛ وقتی کارتان تمام شد حذفشان کنید.",
"arcpkg.links.progress": "در حال دانلود فایل {n} از {count} روی این رایانه…",
"arcpkg.links.title": "آرشیو روی پیوندهای دانلود است",
"arcpkg.noFirstPart": "فایل‌ها دانلود شدند، اما هیچ‌کدام بخش اول یک آرشیو نیستند (‎.zip، ‎.7z، ‎.rar یا ‎.part1.rar). پیوندها را بررسی کنید.",
"fpkg.image.done": "ایمیج بازی نوشته و برای اطمینان بازخوانی شد. آن را روی درایو PS5 کپی کنید («بارگذاری») تا ShadowMount+ مانتش کند.",
