"fpkg.image.folderOnly_v4": "فقط پوشهٔ بازی، ایمیج بازی یا آرشیوی (.zip، .7z، .rar) که بازی در آن است می‌تواند به ایمیج بازی تبدیل شود؛ آرشیو ابتدا در پوشهٔ خروجی باز می‌شود.",
