"engine_problem.port.fix": "«راه‌اندازی دوبارهٔ موتور» را بزنید. اگر نشد، به ps5upload-engine در دیوار آتش یا آنتی‌ویروس اجازه دهید و برنامه را دوباره باز کنید.",
