"always_overwrite_hint_v2": "وقتی مقصد یک ارسال از قبل فایل دارد، تأیید را رد کن. خاموش بگذارید تا پیام بازنویسی / ادامه / لغو را ببینید.",
audit_empty_v2: "هنوز چیزی ثبت نشده. اقدامات برق (بیدار کردن، حالت استراحت، راه‌اندازی مجدد، خاموش کردن)، حذف‌ها، لغو ثبت‌ها، حذف نصب‌ها و نصب‌ها همین‌طور که انجامشان می‌دهید اینجا ظاهر می‌شوند.",
audit_log_description_v3: "سابقه‌ای که در این برنامه روی این کامپیوتر نگه داشته می‌شود از اقدامات برق، حذف‌ها، لغو ثبت‌ها، حذف نصب‌ها و نصب‌ها. ۲۵۶ مورد جدیدتر نگه داشته و قدیمی‌ترها کنار گذاشته می‌شوند؛ دکمه‌ی پاک کردن وجود ندارد، اما پاک کردن داده‌های برنامه یا حافظه‌ی مرورگر آن را پاک می‌کند. ۱۰۰ مورد آخر نمایش داده می‌شود.",
