connection_first_run_nudge_body_v2: "جادوگر راه‌اندازی kstuff و ShadowMount+ را دانلود و ارسال می‌کند و سپس کمک‌یار را، به ترتیب درست. اگر کنسول شما خودش kstuff را بارگذاری می‌کند (یک autoloader، etaHEN)، مرحله‌ی ۲ در زیر فقط کمک‌یار را می‌فرستد.",
