"fpkg.image.zstd": "بسته‌های دارایی zstd (کوچک‌ترین، برای ShadowMount+)",
"fpkg.image.zstd_body": "همه‌چیز جز فایل‌های سیستمی بازی را در بسته‌های zstd قرار می‌دهد و مستقیم و بدون کپی موقت در ایمیج می‌نویسد. ایمیج، ampr-emu-ng از quer3q را به‌عنوان شبیه‌ساز می‌گیرد که پیش از استفاده با یک چکیدهٔ منتشرشده بررسی می‌شود. بازی‌ای که در بسته‌های LZ4 است تبدیل می‌شود. update_emulators را در ShadowMount+ خاموش کنید، وگرنه ممکن است شبیه‌ساز را با یکی عوض کند که نمی‌تواند آن‌ها را بخواند.",
"fpkg.image.zstd_level": "سطح فشرده‌سازی",
"fpkg.image.zstd_runtime": "محیط اجرای بسته‌ها",
"fpkg.image.zstd_runtime_latest": "جدیدترین نسخه (پیش‌فرض)",
"fpkg.image.zstd_runtime_pinned": "آزموده {version}",
"fpkg.image.zstd_runtime_body": "«جدیدترین» آخرین نسخهٔ ampr-emu-ng در GitHub را فقط وقتی به کار می‌برد که با SHA-256 منتشرشدهٔ GitHub برای آن یکی باشد؛ در غیر این صورت یا بدون اینترنت، نسخهٔ آزمودهٔ {version} قرار می‌گیرد. «آزموده» همیشه {version} را به کار می‌برد.",
"fpkg.folder.zstd_body": "بازی را به‌صورت یک پوشهٔ ساده می‌نویسد: همه‌چیز جز فایل‌های سیستمی در بسته‌های zstd، و ampr-emu-ng از quer3q به‌عنوان fakelib/libSceAmpr.sprx. منبع می‌تواند پوشهٔ بازی هم باشد. بسته‌های LZ4 اینجا ارائه نمی‌شوند: فقط در ایمیج .exfat قرار می‌گیرند. update_emulators را در ShadowMount+ خاموش کنید، وگرنه ممکن است شبیه‌ساز را با یکی عوض کند که نمی‌تواند آن‌ها را بخواند.",
"ampr_emu_add_hint": "این بازی فایل‌هایش را از طریق AMPR می‌خواند و شبیه‌ساز ندارد. برخی از این بازی‌ها بدون آن از ایمیج اجرا نمی‌شوند و برخی بدون مشکل کار می‌کنند. ampr_emu 0.4.2.1 از drakmor را اضافه می‌کند؛ یک بار گرفته و با چکیدهٔ شناخته‌شده بررسی می‌شود. ایمیج تغییر نمی‌کند: شبیه‌ساز در پوشهٔ backport از ShadowMount+ قرار می‌گیرد.",
"ampr_emu_done_backport": "به‌صورت backport از ShadowMount+ در {folder} اضافه شد. ایمیج تغییر نکرد. برای امتحان، بازی را اجرا کنید.",
"ampr_emu_done_folder": "به پوشهٔ بازی، {folder}، اضافه شد. برای امتحان، بازی را اجرا کنید.",
"fpkg.fake_sign_note": "{count} فایل اجرایی ساده (بدون امضا) در این بازی هنگام تبدیل امضای جعلی می‌گیرند، وگرنه بازی اجرا نمی‌شود. منبع تغییر نمی‌کند.",
"fpkg.image.ampr_emu": "افزودن شبیه‌ساز AMPR",
"fpkg.image.ampr_emu_body": "این بازی فایل‌هایش را از طریق AMPR می‌خواند و شبیه‌ساز ندارد. برخی از این بازی‌ها بدون آن از ایمیج اجرا نمی‌شوند و برخی بدون مشکل کار می‌کنند. ampr_emu 0.4.2.1 از drakmor را به‌صورت fakelib/libSceAmpr.sprx اضافه می‌کند؛ یک بار از نسخهٔ GitHub آن گرفته و با چکیدهٔ شناخته‌شده بررسی می‌شود.",
"fpkg.image.lz4_placement_note": "ایمیج بسته‌شده را روی حافظهٔ داخلی کنسول نگه دارید: گزارش شده یکی از USB روی صفحهٔ سیاه گیر کرده است. update_emulators را در ShadowMount+ خاموش کنید، وگرنه ممکن است شبیه‌ساز را با نسخه‌ای عوض کند که بسته‌ها را نمی‌خواند.",
"smp_rescan": "اسکن اکنون",
"smp_rescan_done": "ShadowMount+ در حال اسکن است. ایمیج‌های جدید را پیدا می‌کند و بازی‌هایی که mount نشدند دوباره امتحان می‌شوند.",
"rp_picture_pixelated": "پیکسل‌های تیز",
"rp_picture_pixelated_hint": "به‌جای نرم کردن، با لبه‌های تیز بزرگ می‌کند: برای بازی‌های قدیمی.",
"rp_picture_reset": "بازنشانی تصویر",
"rp_picture_off_slow": "ابزارهای تصویر خاموش شد: این دستگاه نتوانست همراهی کند.",
"rp_picture_off_linux": "وضوح و بزرگ‌نمایی خاموش است: با گرافیک امن برنامهٔ لینوکس باعث کندی پخش می‌شوند. Chrome روی لینوکس آن‌ها را دارد.",
