"rp_err_in_use": "دستگاه دیگری از Remote Play روی این PS5 استفاده می‌کند، یا PS5 هنوز جلسه‌ای را تمام می‌کند. Remote Play را روی آن دستگاه ببندید (برنامهٔ PS Remote Play یا chiaki)، سپس «شروع» را بزنید.",
