"rp_err_other": "پخش متوقف شد.",
"rp_err_lost": "اتصال به PS5 در میانهٔ پخش قطع شد. دوباره شروعش کنید؛ اگر تکرار شد، PS5 یا این دستگاه را با کابل وصل کنید.",
"rp_err_rp_off": "Remote Play روی PS5 خاموش است. روی کنسول به تنظیمات › سیستم › Remote Play بروید و «فعال‌سازی Remote Play» را روشن کنید (اگر روشن است، یک بار خاموش و دوباره روشنش کنید)، سپس «شروع» را بزنید. خاکستری است؟ حساب کاربر PS5 باید فعال باشد، و PS5ای که به محیط NP ‏sp-int تغییر داده شده آن را خاموش نگه می‌دارد: آن را به np برگردانید.",
"rp_err_refused": "PS5 شروع Remote Play را رد کرد. روی کنسول تنظیمات › سیستم › Remote Play › فعال‌سازی Remote Play را بررسی کنید (خاموش و دوباره روشن کنید)، در «بازی» › راه‌اندازی «اجازه» را بزنید یا دوباره جفت کنید. کد زیر نشان می‌دهد کدام رد بوده است. هنوز رد می‌کند؟ PS5 را دوباره راه‌اندازی کنید: کنسولی که مدت زیادی روشن بوده ممکن است تا راه‌اندازی دوباره رد کند.",
"web_update_how_docker": "برای به‌روزرسانی، این را در پوشهٔ فایل compose اجرا کنید (Watchtower هم می‌تواند این کار را برایتان انجام دهد):",
"web_update_how_app": "این صفحه از PS5Upload روی رایانهٔ دیگری می‌آید. برنامه را آنجا به‌روز کنید تا این صفحه هم به‌روز شود.",
"rp_err_unreachable": "PS5 در شبکه پاسخ نمی‌دهد. بررسی کنید روشن است، در همان شبکه است و Remote Play در تنظیماتش فعال است.",
"rp_err_video": "PS5 این اندازهٔ تصویر را نپذیرفت. 720p را امتحان کنید.",
"rp_err_no_session_id": "PS5 پخش را پذیرفت اما شروع آن را تمام نکرد. به تلویزیون نگاه کنید، شاید PS5 چیزی می‌پرسد. بازی‌ای که کاربر دیگری روی PS5 شروع کرده نیز می‌تواند آن را نگه دارد: به کاربر خودتان بروید یا آن بازی را ببندید، سپس شروع را بزنید.",
