"mesh_rp_started": "{name} روی این کنسول بازی را شروع کرد",
"rp_keys_body3": "برای بازی با صفحه‌کلید روی تصویر کلیک کنید؛ Esc نشانگر را برمی‌گرداند. برای تمام‌صفحه دوبار کلیک کنید؛ آنجا Esc کوتاه دایره است و نگه داشتن Esc از تمام‌صفحه خارج می‌شود. کلیدها، صدا و موارد دیگر در تنظیمات.",
