"dump_decrypt_risk": "رمزگشایی ممکن است کنسول را هنگ کند",
"dump_decrypt_risk_body": "برای رمزگشایی، کمک‌یار برای هر فایل اجرایی بخشی از سیستم را که همه برنامه‌ها استفاده می‌کنند کوتاه‌مدت جایگزین می‌کند. اگر بازی در همان لحظه فایلی بخواند، کنسول ممکن است هنگ کند و نیاز به خاموش‌کردن اجباری داشته باشد. در این مدت در صفحه شروع بازی بمانید. فقط فریمور تا 13.60؛ در فریمورهای جدیدتر دامپ یک کپی ساده است.",
