"pt_picture_hint": "وقتی خاموش است، این دستگاه فقط دوستانتان را دعوت می‌کند: بدون تصویر، صدا و دسته در اینجا، و بازی دوستانتان ادامه دارد. برای بازی روی تلویزیون.",
"pt_tv_title": "روی تلویزیون بازی می‌کنید؟",
"pt_tv_note": "این پخش با کاربر PS5 که با PS5Upload جفت کرده‌اید وارد شده است. PS را روی DualSense کنسول بزنید و کاربر دیگری را انتخاب کنید: آن کاربر شما روی تلویزیون هستید. انتخاب همان کاربر پخش، پخش را برای همه، از جمله دوستان، تمام می‌کند. برخی بازی‌ها کاربر پخش را هم بازیکن حساب می‌کنند و ممکن است یک جا برای دوستان کمتر شود.",
