"add_sources_no_picker": "این نسخه نمی‌تواند این دستگاه را مرور کند — مسیری را وارد کنید که موتور ببیند.",
"collection.empty_body_v2": "بسته‌ها، پوشه‌های بازی، ایمیج‌های بازی و آرشیوهای داخل آن پیدا و بر اساس بازی گروه‌بندی می‌شوند. چیزی در پوشه تغییر نمی‌کند. پوشه‌ای روی این دستگاه، یک درایو خارجی یا پوشه‌ای روی NAS یا سرور (SMB، FTP، SFTP، WebDAV) مناسب است.",
