"tn_title_device": "Tailscale روی این دستگاه",
"settings_ps5_none_title": "هنوز PS5ای نیست",
"settings_ps5_none_body": "PS5 خود را در صفحهٔ اتصال اضافه کنید؛ سپس تنظیمات مخصوصش اینجاست.",
"settings_ps5_open_connection": "باز کردن اتصال",
"settings_ps5_picker": "PS5",
"settings_ps5_picker_hint": "این تنظیمات فقط مال همین PS5 است. هر کنسول شما تنظیمات خودش را دارد و همراهش به دستگاه‌های دیگرتان می‌رود.",
"auto_bringup_hint_ps5": "وقتی لودر این PS5 (elfldr، پورت 9021) فعال است و کمک‌یار اجرا نمی‌شود، برنامه خودش راه‌اندازی سریع را اجرا می‌کند: فهرست پخش راه‌اندازی این PS5 اگر تعیین کرده باشید، سپس کمک‌یار، سپس فهرست پخش بارگذار خودکار. هر بار که این PS5 روشن می‌شود یک بار؛ پس از حالت استراحت فقط کمک‌یار دوباره فرستاده می‌شود. حدود 90 ثانیه پس از ظاهر شدن لودر صبر می‌کند تا بارگذار خودکار خود کنسول اول کارش را تمام کند. به‌طور پیش‌فرض خاموش است.",
"bringup_playlist_label_ps5": "فهرست پخش راه‌اندازی برای این PS5 (کرنل R/W، SMP)",
"bringup_playlist_hint_ps5": "در راه‌اندازی سریع پیش از کمک‌یار اجرا می‌شود. payloadها به فریمور بستگی دارند، پس هر PS5 فهرست خودش را دارد. فهرست‌های پخش را در Payloadها بسازید.",
"upload_auto_redeploy_on_wake_hint_ps5": "وقتی کمک‌یار این PS5 آفلاین می‌شود (حالت استراحت، تغییر Wi-Fi یا کرش payload)، در پس‌زمینه برای ارسال دوباره‌اش تلاش می‌کند تا کمک‌یار، آستانهٔ فن این PS5 و پورت بارگذاری، وقتی دوباره در دسترس شد، خودشان برگردند. به‌طور پیش‌فرض روشن.",
"keep_ps5_awake_mode_hint_ps5": "زمان‌سنج آماده‌به‌کار خودکار این PS5 را بازنشانی می‌کند تا به حالت استراحت نرود. «هنگام بارگذاری و نصب» از بارگذاری‌های طولانی محافظت می‌کند (دلیل رایج شکست بارگذاری؛ پیش‌فرض). «همیشه هنگام اتصال» این PS5 را تا وقتی کمک‌یارش اجراست و برنامه باز است از حالت استراحت دور نگه می‌دارد. بردن دستی PS5 به حالت استراحت در همهٔ حالت‌ها کار می‌کند.",
"upload_rest_after_hint_ps5": "وقتی صف بارگذاری این PS5 تمام شود، از آن بخواهد به حالت استراحت برود؛ برای صف شبانه کاربردی است. فقط وقتی دست‌کم یک بارگذاری کامل شده باشد (نه پس از توقف یا اجرایی که همه‌اش ناموفق بوده). به‌طور پیش‌فرض خاموش. برخی فریمورها حالت استراحت را رد می‌کنند؛ اگر این PS5 چنین کند، پیامی می‌گیرید.",
"upload_wake_for_uploads_hint_ps5": "وقتی بارگذاری‌ای منتظر این PS5 در حالت استراحت است، سیگنال بیدارباش بفرستد و پس از بازگشت کمک‌یارش ادامه دهد. نیاز دارد بیدارباش برای این PS5 در صفحهٔ اتصال تنظیم شده باشد. به‌طور پیش‌فرض روشن.",
"install_path_fallback_hint_ps5": "آخرین راه برای بسته‌ای که از قبل روی این PS5 است، وقتی بسته را از حافظهٔ خودش رد می‌کند و از این کامپیوتر هم نمی‌تواند بگیرد. فقط برای بازی پایه‌ای که نصب نیست استفاده می‌شود، پس چیزی را حذف نمی‌کند. اثبات‌نشده: روی فریمور 11.20 کار کرده و روی 13.60 رد می‌شود، برای همین برای هر PS5 جداگانه تنظیم می‌شود. اگر امتحانش کردید، لطفاً گزارش دهید که کار کرد یا نه.",
"settings_group_ps5_elsewhere": "بیشتر برای این PS5",
